"""CyberPet — mascota de escritorio.

El robot de la ilustración de referencia, estático en su pose básica,
deslizándose suavemente por TODA la pantalla. Sin animaciones: solo
está ahí, siempre visible encima de tus ventanas.

Controles:
  - Arrastrar con clic izquierdo: mover al robot.
  - Clic derecho: menú (Salir).

En Windows la ventana es 100% transparente (solo se ve el robot).
En Linux/macOS tkinter no soporta color de transparencia, así que se ve
sobre un pequeño recuadro de color.
"""

import os
import random
import tkinter as tk

# Color "llave" que Windows vuelve transparente
TRANSPARENT = "#ff00fe"

FPS_MS = 33

# Imagen del robot (PNG base64) incrustada para que el ejecutable sea
# un único archivo sin recursos externos.
SPRITE_B64 = ""


class CyberPet:
    def __init__(self):
        self.root = tk.Tk()
        self.root.title("CyberPet")
        self.root.overrideredirect(True)
        self.root.attributes("-topmost", True)

        self.img = tk.PhotoImage(data=SPRITE_B64)
        self.w = self.img.width()
        self.h = self.img.height()

        bg = os.environ.get("CYBERPET_BG", TRANSPARENT)  # útil para pruebas
        self.canvas = tk.Canvas(self.root, width=self.w, height=self.h,
                                bg=bg, highlightthickness=0)
        self.canvas.pack()
        self.canvas.create_image(self.w // 2, self.h // 2, image=self.img)
        try:
            self.root.wm_attributes("-transparentcolor", TRANSPARENT)
        except tk.TclError:
            pass  # Linux/macOS: sin transparencia por color

        self.sw = self.root.winfo_screenwidth()
        self.sh = self.root.winfo_screenheight()
        self.x = float(random.randint(0, max(0, self.sw - self.w)))
        self.y = float(random.randint(0, max(0, self.sh - self.h)))
        pos = os.environ.get("CYBERPET_POS")  # útil para pruebas: "x,y"
        if pos:
            px, py = pos.split(",")
            self.x, self.y = float(px), float(py)

        self.state = "pause"       # pause | drift | drag
        self.pause_left = random.randint(30, 120)
        self.target = (self.x, self.y)
        self.drag_dx = 0
        self.drag_dy = 0

        self.canvas.bind("<Button-1>", self.on_press)
        self.canvas.bind("<B1-Motion>", self.on_drag)
        self.canvas.bind("<ButtonRelease-1>", self.on_release)
        self.canvas.bind("<Button-3>", self.on_menu)

        self.menu = tk.Menu(self.root, tearoff=0)
        self.menu.add_command(label="Salir", command=self.root.destroy)

        self.move_window()
        self.tick()

    # ----------------------------------------------------------- eventos
    def on_press(self, event):
        self.state = "drag"
        self.drag_dx = event.x_root - int(self.x)
        self.drag_dy = event.y_root - int(self.y)

    def on_drag(self, event):
        self.x = float(event.x_root - self.drag_dx)
        self.y = float(event.y_root - self.drag_dy)
        self.move_window()

    def on_release(self, _event):
        if self.state == "drag":
            self.state = "pause"
            self.pause_left = random.randint(60, 240)

    def on_menu(self, event):
        self.menu.tk_popup(event.x_root, event.y_root)

    # -------------------------------------------------------------- bucle
    def pick_target(self):
        margin = 10
        tx = random.uniform(margin, max(margin, self.sw - self.w - margin))
        ty = random.uniform(margin, max(margin, self.sh - self.h - margin))
        self.target = (tx, ty)
        self.state = "drift"

    def move_window(self):
        self.x = max(-40.0, min(self.x, float(self.sw - self.w + 40)))
        self.y = max(-20.0, min(self.y, float(self.sh - self.h + 20)))
        self.root.geometry(f"{self.w}x{self.h}+{int(self.x)}+{int(self.y)}")

    def tick(self):
        if self.state == "pause":
            self.pause_left -= 1
            if self.pause_left <= 0:
                self.pick_target()
        elif self.state == "drift":
            tx, ty = self.target
            dx, dy = tx - self.x, ty - self.y
            dist = (dx * dx + dy * dy) ** 0.5
            speed = 2.2
            if dist <= speed:
                self.x, self.y = tx, ty
                self.state = "pause"
                self.pause_left = random.randint(60, 240)
            else:
                self.x += speed * dx / dist
                self.y += speed * dy / dist
            self.move_window()
        self.root.after(FPS_MS, self.tick)

    def run(self):
        self.root.mainloop()


if __name__ == "__main__":
    CyberPet().run()
